namespace kiotty::base {
struct ItemQuery {
    KiottySpecItemKind kind{};                 // 0 이면 전체
    KiottySpecItemCategory category{};         // 0 이면 전체
    std::optional<std::string> parentId;
    std::optional<std::string> text;
    int64_t cut = core::kCurrent;
